night='''
:root{color-scheme:dark;--paper:#0d0e12;--surface:#181a20;--canvas:#111318;--line:#292c35;--ink:#eef0f5;--muted:#959ba8;--accent:#c7f06a;--draw:#9bb4ff;--target:#c7f06a;--font:'Manrope',sans-serif}body{background:#0d0e12}header{height:83px;position:relative;padding:0 42px 0 36px;border-bottom:1px solid var(--line);background:#111217}.brand{font-size:23px;font-weight:700}.brand::before{content:'';width:18px;height:18px;border-radius:50%;border:2px solid var(--accent);box-shadow:inset 0 0 0 4px #111217}.tagline{font-family:'IBM Plex Mono',monospace;font-size:12px;color:#858b98}.circle{background:transparent;border-color:#3a3d48;border-radius:9px}main{display:grid;grid-template-columns:210px minmax(0,1fr);max-width:1400px;margin:auto;padding:0 36px 70px;column-gap:44px}.minigames{grid-column:1;grid-row:1 / span 4;flex-direction:column;overflow:visible;gap:5px;margin:30px 0 0;padding-right:24px;border-right:1px solid var(--line)}.minigames::before{content:'PLAY MODES';font:12px 'IBM Plex Mono',monospace;color:var(--muted);letter-spacing:1px;margin:0 0 14px 12px}.minigames button{text-align:left;padding:12px 14px;color:#969caa;font-size:14px;border-radius:9px;font-weight:500}.minigames .active{background:#262b22;color:var(--accent);border:1px solid #3c4930;padding:11px 13px}.minigames button:hover{color:var(--ink);background:#1b1e25}.minigames .active:hover{color:var(--accent);background:#262b22}.topline{grid-column:2;margin:30px 0 20px;max-width:850px;width:100%;align-self:start}.tabs{background:#191b22;padding:4px;border-radius:9px}.tabs .active{background:#31343f;color:#fff}.layout{grid-column:2;display:block;max-width:850px;width:100%}.game{background:var(--surface);border:1px solid #30333e;border-radius:18px;padding:24px 36px 30px;box-shadow:0 25px 80px #00000020}.gamebar{font-family:'IBM Plex Mono',monospace;color:#9097a5;border-bottom:1px solid var(--line);padding-bottom:21px}.score{color:#eef0f5}.progress i{background:#343844}.progress .current{opacity:1;background:var(--accent);box-shadow:0 0 9px #c7f06a22}.mixed-question{padding:28px 0 22px}.eyebrow{font-family:'IBM Plex Mono',monospace;color:var(--accent)}.mixed-question h1{font-size:38px;font-weight:600}.spatial-wrap{max-width:470px}.spatial-wrap canvas{border:1px solid #303440;border-radius:12px}.primary{color:#151a10;background:var(--accent);border-radius:9px}.primary:hover{background:#d7fa92}.secondary{border-color:#3b3f4c;background:#242730}.points{color:var(--accent)}.type-overlay-target{color:#c7f06a1a;-webkit-text-stroke-color:#c7f06a}.chosen-swatch{border-color:#4a5060}.colour-caption{color:#969caa}.memory-stage,.type-specimen{border:1px solid #303440;border-radius:12px}.pulse{border:1px solid #3c4350;background:#111318}.pulse.lit{background:var(--accent);border-color:var(--accent)}.beat-count{color:var(--accent)}aside{display:none}footer{grid-column:2;max-width:850px;margin-top:24px;font-family:'IBM Plex Mono',monospace;font-size:12px}.option-switch{background:#191b22;border-color:#373c47}.time-cue strong{color:var(--accent);font-family:'IBM Plex Mono',monospace;font-size:104px;letter-spacing:-7px}.bigscore{font-family:'IBM Plex Mono',monospace}.minigames button:focus-visible{outline-offset:0}@media(max-width:850px){header{padding:0 24px;height:73px}main{display:block;padding:0 20px 75px}.minigames{flex-direction:row;overflow-x:auto;border-right:0;border-bottom:1px solid var(--line);padding:0 0 12px;margin:20px 0}.minigames::before{display:none}.topline{margin:20px 0}.game{padding:24px}.mixed-question h1{font-size:32px}footer{margin-top:24px}}@media(max-width:600px){.brand{font-size:22px}.game{padding:20px;border-radius:14px}.gamebar{gap:8px}.mixed-question{padding-top:24px}.option-switch span{display:none}}
'''
base+='\n@media(max-width:600px){.gamebar{gap:8px}.gamebar #roundlabel,.gamebar .score{white-space:nowrap}.gamebar .progress{gap:4px}.gamebar .progress i{width:12px}}\n.option-switch[hidden]{display:none}body:has(.feedback) .mixed-controls>button:disabled,body:has(.feedback) .preview-actions{display:none}\n'
focus+='\n.brand{text-transform:lowercase}\n'
styles={'focus':focus,'night-lab':night}
base=Path('src/design-options/fonts.css').read_text()+base
out=Path('public')
out.mkdir(exist_ok=True)
# Browser canvas colours follow the preview's theme; colour-memory target values stay untouched.
themed=script.replace("function shell(q,content,controls){gamebar();","function shell(q,content,controls){$('playarea').dataset.puzzle=q.type;gamebar();")
themed=themed.replace("'#f3f6ff'","getComputedStyle(document.documentElement).getPropertyValue('--canvas').trim()")
themed=themed.replace("'#2448ed'","getComputedStyle(document.documentElement).getPropertyValue('--draw').trim()")
themed=themed.replace("start();updateAside();",'''const demoGame=new URLSearchParams(location.search).get('game');if(['mix','view3d','balance','halfhalf','motion','perspective','proportion','rhythm','angle','memory','time','timeline','duration'].includes(demoGame)){mini=demoGame;document.querySelectorAll('[data-mini]').forEach(b=>b.classList.toggle('active',b.dataset.mini===mini));}start(new URLSearchParams(location.search).get('mode')==='practice'?'practice':'daily');updateAside();startCentralDayRollover();''')
theme_preference=Path('src/design-options/theme-preference.js').read_text()
mobile_play=(Path('src/design-options')/'mobile-play.css').read_text()
themed=themed.replace("'use strict';", "'use strict';\n"+Path('src/design-options/player-storage.js').read_text(),1)
themed=themed.replace("render();}\nfunction gamebar", "if(restoreDailyGame()){if(index===deck.length){finish();return;}}else saveDailyGame();updateStorageNotice();render();}\nfunction gamebar")
# Save committed answers immediately, before a player presses Next or closes the tab.
themed=themed.replace('results.push({q,guess:value,score});', 'results.push({q,guess:value,score});saveDailyGame();')
analytics_config=json.loads(Path('src/design-options/analytics-config.json').read_text())
if analytics_config['websiteId'] and not re.fullmatch(r'[0-9a-fA-F-]{36}',analytics_config['websiteId']):
 raise ValueError('Invalid Umami website ID')
if not analytics_config['scriptUrl'].startswith('https://'):
 raise ValueError('Umami script must use HTTPS')
analytics_source='const ANALYTICS_CONFIG='+json.dumps(analytics_config).replace('<','\\u003c')+';\n'+Path('src/design-options/analytics.js').read_text()
themed=themed.replace("'use strict';", "'use strict';\n"+analytics_source,1)
themed=themed.replace('results.push({q,guess:value,score});saveDailyGame();', 'analyticsStarted();results.push({q,guess:value,score});saveDailyGame();analyticsCompleted();')
themed=themed.replace("'use strict';", "'use strict';\n"+Path('src/design-options/friend-challenge.js').read_text(),1)
themed=themed.replace('function gamebar(){', 'function gamebar(){renderFriendChallenge();')
themed+='\nsetupAnalytics();\n'
html=html.replace('<script src="game.js"></script>', '<dialog id="history-dialog" class="history-dialog" aria-labelledby="history-title"><div class="history-heading"><h2 id="history-title">Recent results</h2><form method="dialog"><button class="history-close" aria-label="Close recent results">×</button></form></div><div id="history-content"></div></dialog><script src="game.js"></script>')
themed+='\nbindHistoryNavigation();\n' 
html=html.replace('<div class="gamebar">','<p id="friend-challenge" class="friend-challenge" role="status" hidden></p><p id="save-note" class="save-note" role="status" hidden></p><div class="gamebar">')
common_css=mobile_play+Path('src/design-options/trivia.css').read_text()+Path('src/design-options/theme-switcher.css').read_text()+Path('src/design-options/summary-comparisons.css').read_text()+Path('src/design-options/share-results.css').read_text()+Path('src/design-options/player-storage.css').read_text()+Path('src/design-options/play-navigation.css').read_text()
theme_assets={key:key+'.css?v='+hashlib.sha256((base+css+common_css).encode()).hexdigest()[:12] for key,css in styles.items()}
theme_preference='window.perceptionThemeAssets='+json.dumps(theme_assets)+';\n'+theme_preference
for key,css in styles.items():
 css+=common_css
 (out/(key+'.css')).write_text(base+css)
 page=html.replace('<meta charset="utf-8">','<meta charset="utf-8"><script>'+theme_preference+'</script>').replace('<link rel="stylesheet" href="style.css">','').replace('<script src="game.js"></script>','<script>'+themed+'</script>')
 page=page.replace('<title>Perception — five puzzles for a sharper eye</title>','<title>Perception</title>')
 page=page.replace('<span class="tagline">Five puzzles. A sharper sense.</span>', '<span class="tagline">'+'A daily perception game'+'</span>')
 page=page.replace('<button id="help"', '<div class="option-switch"><svg class="theme-icon theme-icon-system" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/></svg><svg class="theme-icon theme-icon-light" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg><svg class="theme-icon theme-icon-dark" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/></svg><select id="theme-select" aria-label="Theme"><option value="system">System</option><option value="focus">Light</option><option value="night-lab">Dark</option></select></div><button id="help"')
 page=page.replace('</body>','<p class="site-links"><a href="about.html">About &amp; how to play</a><a href="https://github.com/chipgpt/perception" target="_blank" rel="noopener">GitHub</a></p><script>'+Path('src/design-options/theme-switcher.js').read_text()+'</script></body>')
 (out/(key+'.html')).write_text(page)
(out/'index.html').write_text((out/'night-lab.html').read_text())
# Preserve old bookmarks and maintenance file paths with a Night Lab alias.
(out/'studio.html').write_text((out/'night-lab.html').read_text())
(out/'studio.css').write_text((out/'night-lab.css').read_text())
(Path('src/design-options')/'game-themed.js').write_text(themed)
build_discovery_files()
print('Built Night Lab and Focus with the same game logic.')
